CREATE TABLE assets (
	id VARCHAR NOT NULL,
	work_id INTEGER NOT NULL,
	role VARCHAR NOT NULL,
	page_index INTEGER NOT NULL,
	relative_path TEXT,
	source_url TEXT,
	state VARCHAR NOT NULL,
	byte_size INTEGER,
	sha256 VARCHAR,
	width INTEGER,
	height INTEGER,
	verified_at DATETIME,
	file_mtime_ns INTEGER,
	file_identity INTEGER,
	error TEXT,
	PRIMARY KEY (id),
	UNIQUE (work_id, role, page_index),
