	FOREIGN KEY(work_id) REFERENCES works (id)
);
CREATE TABLE works (
	id INTEGER NOT NULL,
	pixiv_illust_id VARCHAR NOT NULL,
	artist_id INTEGER NOT NULL,
	title TEXT NOT NULL,
	type VARCHAR NOT NULL,
	page_count INTEGER NOT NULL,
	caption TEXT NOT NULL,
