	time_basis VARCHAR NOT NULL,
	legacy_posted_at TEXT,
	downloaded_at DATETIME NOT NULL,
	source_metadata JSON NOT NULL,
	PRIMARY KEY (id),
	CHECK (page_count >= 1),
	UNIQUE (pixiv_illust_id),
	FOREIGN KEY(artist_id) REFERENCES artists (id)
);
